#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
set -Eeuo pipefail
project=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
output=${1:-$project/xray_reality_bootstrap.sh}
temporary=$(mktemp "${output}.XXXXXX")
trap 'rm -f -- "$temporary"' EXIT
{
  cat <<'EOF'
#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
# Generated by scripts/build.sh. Edit lib/, then rebuild.
# Modified from braydos-h's original installer: security and operational overhaul.
set -Eeuo pipefail
ENTRY_PATH=${BASH_SOURCE[0]}
STANDALONE=true
PROJECT_DIR=''
data() {
  python3 - "$@" <<'XRAY_BOOTSTRAP_PYTHON'
EOF
  cat "$project/lib/data.py"
  printf '\nXRAY_BOOTSTRAP_PYTHON\n}\n'
  for module in common config transaction xray systemd reality firewall ssh host backup clients diagnostics main; do
    cat "$project/lib/$module.sh"
    printf '\n'
  done
  # shellcheck disable=SC2016
  printf 'if [[ ${BASH_SOURCE[0]} == "$0" ]]; then main "$@"; fi\n'
} >"$temporary"
bash -n "$temporary"
chmod 755 "$temporary"
mv -f -- "$temporary" "$output"
